H.background();
const dm = Math.max(P.dm, 0);
const c = 2.998e8;
const E = dm * 1.6605e-27 * c * c;
const EMeV = E / 1.602e-13;
H.text("Mass-energy equivalence: E = m c^2", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("A mass defect dm releases energy E = dm c^2", 24, 52, { color: H.colors.sub, size: 13 });
const cx = 220, cy = 300;
const pulse = 1 + 0.12 * Math.sin(t * 3);
H.circle(cx, cy, 46 * pulse, { fill: H.colors.panel, stroke: H.colors.accent, width: 2 });
H.text("dm", cx, cy - 8, { color: H.colors.ink, size: 16, weight: 700, align: "center", baseline: "middle" });
H.text(dm.toFixed(3) + " u", cx, cy + 14, { color: H.colors.sub, size: 12, align: "center", baseline: "middle" });
const nRays = 12;
for (let i = 0; i < nRays; i++) {
  const ang = (i / nRays) * Math.PI * 2;
  const frac = ((t * 0.8 + i / nRays) % 1);
  const r0 = 50, r1 = 230;
  const rr = r0 + frac * (r1 - r0);
  const xx = cx + Math.cos(ang) * rr;
  const yy = cy + Math.sin(ang) * rr;
  const a = dm > 0 ? (1 - frac) : 0;
  if (a > 0.02) H.circle(xx, yy, 3 + 3 * a, { fill: H.colors.yellow });
}
H.rect(520, 170, 340, 150, { fill: H.colors.panel, stroke: H.colors.grid, width: 1, radius: 8 });
H.text("Energy released", 540, 200, { color: H.colors.sub, size: 13 });
H.text("E = " + E.toExponential(2) + " J", 540, 234, { color: H.colors.accent2, size: 16, weight: 700 });
H.text("E = " + EMeV.toFixed(1) + " MeV", 540, 264, { color: H.colors.good, size: 15, weight: 700 });
H.text("(1 u = 931.5 MeV/c^2)", 540, 296, { color: H.colors.sub, size: 12 });
